import{_ as o,o as t,c as r,ae as i}from"./chunks/framework.BX6FPmO9.js";const p=JSON.parse('{"title":"本地開發","description":"","frontmatter":{},"headers":[],"relativePath":"runbooks/local-dev.md","filePath":"runbooks/local-dev.md"}'),l={name:"runbooks/local-dev.md"};function n(d,e,c,a,s,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="本地開發" tabindex="-1">本地開發 <a class="header-anchor" href="#本地開發" aria-label="Permalink to &quot;本地開發&quot;">​</a></h1><p><strong>類型</strong>：runbook | <strong>權重</strong>：1</p><p>本文件說明分支與 PR、CI 檢查、依賴更新與大型協作建議。</p><h2 id="分支與-pr" tabindex="-1">分支與 PR <a class="header-anchor" href="#分支與-pr" aria-label="Permalink to &quot;分支與 PR&quot;">​</a></h2><ul><li><strong>主分支</strong>：<code>main</code>（可選 <code>develop</code> 作為整合分支）。</li><li><strong>功能開發</strong>：自 <code>main</code> 開 <code>feature/xxx</code> 或 <code>fix/xxx</code>，完成後開 PR 合回 <code>main</code>。</li><li><strong>PR 合併前</strong>：CI 必須全綠（見下方 CI 檢查項）；建議至少一人 Review 後再合併。</li></ul><h2 id="ci-檢查-github-actions" tabindex="-1">CI 檢查（GitHub Actions） <a class="header-anchor" href="#ci-檢查-github-actions" aria-label="Permalink to &quot;CI 檢查（GitHub Actions）&quot;">​</a></h2><ul><li><strong>CI workflow</strong>（<code>.github/workflows/ci.yml</code>）在 PR / push 到 <code>main</code> 時執行，<strong>build、test、lint 皆通過才放行</strong>： <ul><li><strong>Build</strong>：<code>pnpm run build</code></li><li><strong>Test</strong>：<code>pnpm run test</code>（產出 <code>reports/vitest-results.json</code>、<code>reports/junit.xml</code>；JUnit 會由 <strong>Publish Test Results</strong> 步驟顯示在 GitHub Actions 該次 run 的測試摘要）</li><li><strong>Lint</strong>：<code>lint:filenames</code>、<code>lint:handlers</code>、ESLint（strict）、<code>typecheck</code>（產出 <code>reports/eslint-report.json</code> 供失敗時彙整）</li></ul></li><li><strong>失敗時</strong>：會產出說明報告（<code>reports/ci-failure-summary.md</code>）並上傳為 Artifact <strong>ci-reports</strong>（保留 7 天），PR 的 Job summary 也會顯示簡要說明。</li><li>合併前請在本地執行：<code>pnpm run build</code>、<code>pnpm run test</code>、<code>pnpm run lint:ci</code>。</li></ul><h2 id="依賴更新" tabindex="-1">依賴更新 <a class="header-anchor" href="#依賴更新" aria-label="Permalink to &quot;依賴更新&quot;">​</a></h2><ul><li>使用 <strong>Dependabot</strong>（<code>.github/dependabot.yml</code>）自動開 PR 更新依賴。</li><li>建議合併前跑過 CI 與基本手動檢查，再合併 Dependabot PR。</li></ul><h2 id="大型協作建議-需在-github-設定" tabindex="-1">大型協作建議（需在 GitHub 設定） <a class="header-anchor" href="#大型協作建議-需在-github-設定" aria-label="Permalink to &quot;大型協作建議（需在 GitHub 設定）&quot;">​</a></h2><ol><li><p><strong>Branch protection（main）</strong></p><ul><li>要求 PR 通過後才能合併。</li><li>要求 CI 通過（CI workflow：build / test / lint）。</li><li>可選：要求至少 1 位 Review、禁止 force push。</li></ul></li><li><p><strong>CODEOWNERS</strong>（可選）</p><ul><li>在 <code>.github/CODEOWNERS</code> 指定目錄負責人，PR 會自動請求對應人員 Review。</li></ul></li><li><p><strong>Issue / PR 範本</strong></p><ul><li>已提供 <code>.github/ISSUE_TEMPLATE</code> 與 <code>pull_request_template.md</code>，可依團隊習慣微調。</li></ul></li><li><p><strong>Environment 保護（部署控制）</strong></p><ul><li>建立 <code>preview</code>、<code>production</code> environments。</li><li><code>production</code> 建議啟用 required reviewers，限制可部署人員。</li><li>在 <code>.github/workflows/deploy-vercel.yml</code> 透過 environment gate 控制上線。</li></ul></li></ol><h2 id="建議新增的套件或步驟-可選" tabindex="-1">建議新增的套件或步驟（可選） <a class="header-anchor" href="#建議新增的套件或步驟-可選" aria-label="Permalink to &quot;建議新增的套件或步驟（可選）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td><strong>E2E 測試</strong></td><td>若需端對端測試，可引入 <strong>Playwright</strong> 或 <strong>Cypress</strong>，並在 CI 中跑 E2E。</td></tr><tr><td><strong>Main 建置</strong></td><td>已併入 <code>ci.yml</code>（push <code>main</code> 時與 PR 同一套檢查）；不再維護獨立的 <code>deploy.yml</code>。</td></tr><tr><td><strong>可控部署</strong></td><td>使用 <code>.github/workflows/deploy-vercel.yml</code> 手動部署 preview/production。</td></tr><tr><td><strong>可控發版</strong></td><td>使用 <code>.github/workflows/release.yml</code> 手動建立 tag 與 GitHub Release。</td></tr></tbody></table><h2 id="agent-runtime-可選" tabindex="-1">Agent Runtime（可選） <a class="header-anchor" href="#agent-runtime-可選" aria-label="Permalink to &quot;Agent Runtime（可選）&quot;">​</a></h2><ul><li>啟動獨立 Agent HTTP：<code>pnpm run dev:agent</code>（預設 <code>http://127.0.0.1:3002</code>，見 <code>services/agent-runtime/README.md</code>）。</li><li>Remix 若要以 HTTP 連線 Agent：設定 <strong><code>AGENT_RUNTIME_URL=http://127.0.0.1:3002</code></strong>；未設定時 <code>api.chat</code> 使用同 process 的 <code>@ai-search-portal/agent-core</code>。</li><li><strong>Local RAG</strong>（in-memory docs）：<code>AGENT_RAG_MODE=local</code> 再啟動 dev；retrieve 會命中 <code>packages/agent-core/src/rag/local-store.ts</code> 內建文件。</li><li><strong>Items tool</strong>：另開 <code>pnpm run dev:api</code>（port 3001），設定 <code>AGENT_EXECUTE_TOOLS=1</code> 或 <code>ITEMS_API_URL=http://127.0.0.1:3001/api/v1/items</code>；chat 串流會執行 <code>items.lookup</code>。</li><li><strong>Offline eval</strong>：<code>pnpm run test:labs</code>、<code>pnpm run eval:offline</code> → <code>reports/eval-YYYY-MM-DD.json</code>（見 <code>labs/eval-runner/</code>）。</li><li><strong>Langfuse（可選）</strong>：<code>pnpm run observability:up</code> → 在 UI 建立 project keys → <code>.env.local</code> 設 <code>LANGFUSE_*</code> → <code>pnpm run observability:smoke</code> 或一般 chat。見 <code>labs/observability/README.md</code>。</li><li><strong>Catalog search</strong>：<code>/catalog-search</code> — product shell + SDK DataTable.</li><li>架構決策見 <a href="./../architecture/ai-product/README.html">ai-product</a>。</li></ul><h2 id="相關文件" tabindex="-1">相關文件 <a class="header-anchor" href="#相關文件" aria-label="Permalink to &quot;相關文件&quot;">​</a></h2><ul><li><a href="./../../CONTRIBUTING.html">CONTRIBUTING.md</a>：貢獻流程與品質檢查</li><li><a href="./../conventions/coding-conventions.html">coding-conventions</a>：命名與程式規範</li><li><a href="./../architecture/system-overview.html">system-overview</a>：架構說明</li><li><a href="./deployment.html">deployment</a>：部署（Vercel）</li></ul>',17)])])}const h=o(l,[["render",n]]);export{p as __pageData,h as default};
